public class Solution {
  /**
   * dp[i] = 排版前 i 个词的最小总坏度（第 i 个词之后是行边界）。
   * 枚举最后一行的起点 j：line = pre[i] - pre[j] - 1 是行占用宽度（pre 里每个词多算 1 个空格）。
   * 最后一行（i == n）不计坏度。j 递减到行宽超过 lineWidth 就 break：
   * 因为每个词至少占 1 + 1 = 2，一行最多 lineWidth 个词 → 转移数被 lineWidth 界住，O(n * W)。
   */
  public static int minLayoutSlack(int[] wordWidths, int lineWidth) {
    int n = wordWidths.length;
    if (n == 0) return 0;
    int[] pre = new int[n + 1];
    for (int k = 0; k < n; k++) {
      if (wordWidths[k] <= 0) throw new IllegalArgumentException("word width must be positive");
      if (wordWidths[k] > lineWidth) return -1;      // 单词超版心：不可排版
      pre[k + 1] = pre[k] + wordWidths[k] + 1;
    }
    final int INF = Integer.MAX_VALUE / 4;
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
      for (int j = i - 1; j >= 0; j--) {
        int line = pre[i] - pre[j] - 1;
        if (line > lineWidth) break;                 // 再往前只会更宽，剪枝
        int slack = (i == n) ? 0 : (lineWidth - line) * (lineWidth - line);
        if (dp[j] + slack < dp[i]) dp[i] = dp[j] + slack;
      }
    }
    return dp[n];
  }
}

