public class Solution {
  // 朴素：greedy first-fit —— 当前行能塞就塞，塞不下才换行。
  // 在 [[4,1,1,1,4]] / 6 这类输入上会比最优解差：第一行塞成 [4,1,1] 后，
  // 剩下的 1 和 4 无法成行，产生 (6-3)^2 = 9 的碎空间，而最优解是 5。
  public static int minLayoutSlack(int[] wordWidths, int lineWidth) {
    int n = wordWidths.length;
    if (n == 0) return 0;
    for (int width : wordWidths) {
      if (width <= 0) throw new IllegalArgumentException("word width must be positive");
      if (width > lineWidth) return -1;
    }
    int total = 0;
    int pos = 0;
    while (pos < n) {
      int used = wordWidths[pos];
      int next = pos + 1;
      while (next < n && used + 1 + wordWidths[next] <= lineWidth) {
        used += 1 + wordWidths[next];
        next++;
      }
      if (next < n) total += (lineWidth - used) * (lineWidth - used);
      pos = next;
    }
    return total;
  }
}
